c3_yfight0:{who:'yu',title:'남윤아와의 다툼',text:'남윤아 씨랑은 지난주에 제 키보드 소리 때문에 한 번 다툰 적이 있어요.',keys:['남윤아','윤아','다툼','싸웠','소음','불만','다툰']},
