  if(q.includes('힌트')||q.includes('막혔')||q.includes('모르겠'))r=hintFor(c,cs);
  else if(q.includes('정리')){const n=cs.known.length;r=n?`지금 카드 ${n}장, 어긋나는 점 ${activeConflicts(c,cs).length}개. `+hintFor(c,cs):'아직 들은 게 없잖아. 관계자부터 만나.'}
